{"path": "middleware.ts", "content": "import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'

/**
 * Middleware runs on every matched request before the route handler.
 * Here it tags every response with a unique X-Request-Id and logs the pathname.
 */
export function middleware(request: NextRequest) {
  // Generate a unique id for this request (crypto.randomUUID is available in
  // both the Node.js and Edge runtimes used by Next.js middleware).
  const requestId = crypto.randomUUID()

  // Log the request pathname to the console.
  console.log(`[middleware] request pathname: ${request.nextUrl.pathname}`)

  // Forward the request and attach the custom header to the response.
  const response = NextResponse.next()
  response.headers.set('X-Request-Id', requestId)

  return response
}

/**
 * Match all routes except static assets and Next.js internals.
 * See https://nextjs.org/docs/app/building-your-application/routing/middleware
 */
export const config = {
  matcher: [
    /*
     * Match all request paths except for the ones starting with:
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico, robots.txt (metadata files)
     */
    '/((?!_next/static|_next/image|favicon.ico|robots.txt).*)',
  ],
}
"}

